import{_ as i,H as l,o as t,c as p,aN as r,q as o,s as A,a,l as s,aT as n}from"./chunks/framework.D31DlcCL.js";const h=JSON.parse('{"title":"AI大模型修仙传（八）：RAG与向量数据库——怎么让AI不再“胡说八道”？","description":"为什么大模型总是“一本正经地胡说八道”？一文看懂RAG（检索增强生成）与向量数据库的底层逻辑，带你给AI装上“外脑”！","frontmatter":{"title":"AI大模型修仙传（八）：RAG与向量数据库——怎么让AI不再“胡说八道”？","date":"2026-04-01T00:00:00.000Z","categories":["AI"],"tags":["RAG","向量数据库","大模型","Embeddings"],"description":"为什么大模型总是“一本正经地胡说八道”？一文看懂RAG（检索增强生成）与向量数据库的底层逻辑，带你给AI装上“外脑”！"},"headers":[],"relativePath":"posts/ai-series-8-rag-vector-db.md","filePath":"posts/ai-series-8-rag-vector-db.md","lastUpdated":null}'),g={name:"posts/ai-series-8-rag-vector-db.md"};function B(d,E,D,m,_,u){const e=l("Mermaid");return t(),p("div",null,[E[3]||(E[3]=r('<h1 id="ai大模型修仙传-八-rag与向量数据库——怎么让ai不再-胡说八道" tabindex="-1">AI大模型修仙传（八）：RAG与向量数据库——怎么让AI不再“胡说八道”？ <a class="header-anchor" href="#ai大模型修仙传-八-rag与向量数据库——怎么让ai不再-胡说八道" aria-label="Permalink to &quot;AI大模型修仙传（八）：RAG与向量数据库——怎么让AI不再“胡说八道”？&quot;">​</a></h1><blockquote><p><strong>💡 博主导读</strong>：企业落地AI最大的痛点就是“幻觉”和“数据隐私”。RAG的出现完美解决了这两个问题。作为技术博主，今天我用三张架构图，带你打通RAG的任督二脉。</p></blockquote><h1 id="ai大模型修仙传-八-rag与向量数据库——怎么让ai不再-胡说八道-1" tabindex="-1">AI大模型修仙传（八）：RAG与向量数据库——怎么让AI不再“胡说八道”？ <a class="header-anchor" href="#ai大模型修仙传-八-rag与向量数据库——怎么让ai不再-胡说八道-1" aria-label="Permalink to &quot;AI大模型修仙传（八）：RAG与向量数据库——怎么让AI不再“胡说八道”？&quot;">​</a></h1><p>各位道友，欢迎回到《AI大模型修仙传》。</p><p>在上一回中，我们讲到大模型（LLM）经过“预训练”和“微调”的雷劫，终于修炼出了极其强大的语言能力，能作诗、能写代码，简直是无所不知的陆地神仙。</p><p>但只要你真正在工作里用过它，一定会遇到一个让人高血压的场景：<strong>它居然会“一本正经地胡说八道”！</strong></p><p>你问它：“林黛玉倒拔垂杨柳是在哪一回？” 它面不改色心不跳地回答：“林黛玉倒拔垂杨柳出自《红楼梦》第三回，展现了她体弱多病外表下隐藏的惊人神力……”</p><p>不仅如此，如果你问它你们公司昨天刚发的内部文件规定，它更是两眼一抹黑，纯靠编。</p><p>在AI界，这种“走火入魔”的现象有一个专业的学名，叫<strong>幻觉（Hallucination）</strong>。</p><p>今天，我们就来聊聊目前AI界最火、最接地气、也是解决“幻觉”最有效的功法——<strong>RAG（检索增强生成）</strong>，以及它的核心法宝<strong>向量数据库（Vector Database）</strong>。</p><hr><h2 id="一、-为什么大模型爱-脑补" tabindex="-1">一、 为什么大模型爱“脑补”？ <a class="header-anchor" href="#一、-为什么大模型爱-脑补" aria-label="Permalink to &quot;一、 为什么大模型爱“脑补”？&quot;">​</a></h2><p>要治病，先找病根。大模型为什么会产生幻觉？</p><p><strong>因为大模型的本质，是一个“文科生”，而不是一个“数据库”。</strong></p><p>在训练时，大模型阅读了互联网上亿万级别的文本，但它并没有把这些文本像U盘一样“存”下来，而是把它们压缩成了神经网络里的参数（权重）。这就好比你考前狂背了一本《辞海》，考场上你虽然大概记得意思，但要你一字不差地默写第250页的内容，你肯定写不出，只能靠语感“编”。</p><p>更要命的是，大模型的知识库是<strong>静态</strong>的。如果它去年就闭关锁国停止了训练，那它绝对不知道今年新出的手机长什么样。</p><p>那怎么办？让它重新训练（重新背书）？ 算了吧道友，训练一次要烧掉几百万美金的电费，老板的钱包扛不住啊。</p><p>于是，机智的程序员们发明了一套“作弊”神技——<strong>RAG</strong>。</p><hr><h2 id="二、-rag-给ai发一张-开卷考试-的准考证" tabindex="-1">二、 RAG：给AI发一张“开卷考试”的准考证 <a class="header-anchor" href="#二、-rag-给ai发一张-开卷考试-的准考证" aria-label="Permalink to &quot;二、 RAG：给AI发一张“开卷考试”的准考证&quot;">​</a></h2>',20)),(t(),o(n,null,{default:A(()=>[s(e,{id:"mermaid-58",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20User%5B%E7%94%A8%E6%88%B7%E6%8F%90%E9%97%AE%5D%20--%3E%20Search%5B1.%20%E6%A3%80%E7%B4%A2%20R%3A%20%E4%BB%8E%E7%9F%A5%E8%AF%86%E5%BA%93%E5%AF%BB%E6%89%BE%E7%9B%B8%E5%85%B3%E7%89%87%E6%AE%B5%5D%0A%20%20%20%20Search%20--%3E%20Augment%5B2.%20%E5%A2%9E%E5%BC%BA%20A%3A%20%E6%8B%BC%E6%8E%A5%E9%97%AE%E9%A2%98%E4%B8%8E%E5%8F%82%E8%80%83%E8%B5%84%E6%96%99%5D%0A%20%20%20%20Augment%20--%3E%20Gen%5B3.%20%E7%94%9F%E6%88%90%20G%3A%20LLM%E6%A0%B9%E6%8D%AE%E8%B5%84%E6%96%99%E4%BD%9C%E7%AD%94%5D%0A%20%20%20%20Gen%20--%3E%20Final%5B%E4%B8%A5%E8%B0%A8%E5%87%86%E7%A1%AE%E7%9A%84%E5%9B%9E%E7%AD%94%5D%0A%20%20%20%20style%20Augment%20fill%3A%23bbf%2Cstroke%3A%23333%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=r('<p><strong>RAG（Retrieval-Augmented Generation，检索增强生成）</strong>，名字听起来像什么高深的心法，其实翻译成大白话就是：<strong>开卷考试</strong>。</p><p>既然你记不住，那你就别背了。我直接把参考书搬到考场里，你看着书答题不就行了？</p><p>RAG 的工作流简直简单粗暴且优雅：</p><ol><li><strong>R（Retrieval / 检索）</strong>：用户提问后，系统先不急着让AI回答，而是先去“藏经阁”（资料库）里搜集和问题相关的参考资料。</li><li><strong>A（Augmented / 增强）</strong>：把搜集到的资料，和用户的原始问题打包在一起，形成一个超大的Prompt（提示词）。</li><li><strong>G（Generation / 生成）</strong>：把这个大包裹扔给大模型，并严厉警告它：“<strong>只准根据我给你的参考资料回答，找不到就说不知道，敢自己瞎编就扣你工资！</strong>”</li></ol><p>有了这套外挂，大模型瞬间从“满嘴跑火车”变成了“严谨的考据党”。</p><p>但这里出现了一个致命的工程问题：<strong>怎么在浩如烟海的“藏经阁”里，一瞬间精准地找到那几段最相关的参考资料？</strong></p><p>这就必须请出我们的两大镇派法宝：<strong>Embeddings（向量化）</strong> 和 <strong>向量数据库</strong>。</p><hr><h2 id="三、-embeddings-万物皆可化作-坐标系" tabindex="-1">三、 Embeddings：万物皆可化作“坐标系” <a class="header-anchor" href="#三、-embeddings-万物皆可化作-坐标系" aria-label="Permalink to &quot;三、 Embeddings：万物皆可化作“坐标系”&quot;">​</a></h2>',9)),(t(),o(n,null,{default:A(()=>[s(e,{id:"mermaid-98",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Text1%5B%E8%8B%B9%E6%9E%9C%E6%89%8B%E6%9C%BA%5D%20--%3E%20Model%5BEmbedding%E6%A8%A1%E5%9E%8B%5D%0A%20%20%20%20Text2%5B%E5%8D%8E%E4%B8%BA%E6%89%8B%E6%9C%BA%5D%20--%3E%20Model%0A%20%20%20%20Text3%5B%E6%A9%98%E5%AD%90%E6%B0%B4%E6%9E%9C%5D%20--%3E%20Model%0A%20%20%20%20Model%20--%3E%20V1(%5B%E5%90%91%E9%87%8F%E5%9D%90%E6%A0%87%3A%200.1%2C%200.9...%5D)%0A%20%20%20%20Model%20--%3E%20V2(%5B%E5%90%91%E9%87%8F%E5%9D%90%E6%A0%87%3A%200.05%2C%200.88...%5D)%0A%20%20%20%20Model%20--%3E%20V3(%5B%E5%90%91%E9%87%8F%E5%9D%90%E6%A0%87%3A%200.85%2C%200.05...%5D)%0A%20%20%20%20V1%20-.-%3E%7C%E8%B7%9D%E7%A6%BB%E6%9E%81%E8%BF%91%2C%20%E8%AF%AD%E4%B9%89%E7%9B%B8%E4%BC%BC%7C%20V2%0A%20%20%20%20V1%20-.-%3E%7C%E8%B7%9D%E7%A6%BB%E6%9E%81%E8%BF%9C%2C%20%E8%AF%AD%E4%B9%89%E6%97%A0%E5%85%B3%7C%20V3%0A%20%20%20%20style%20Model%20fill%3A%23dfd%2Cstroke%3A%23333%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p>在传统的数据库里（比如 MySQL），我们是怎么搜索的？<strong>关键词匹配</strong>。 你搜“苹果”，系统就老老实实去帮你找带有“苹”和“果”这两个字的句子。</p><p>但语言是极其复杂的。 如果用户搜“乔布斯创立的公司”，传统数据库就傻眼了，因为这句话里根本没有“苹果”两个字！</p><p>这就需要大模型出马了。AI不认识字，但它懂数学。<strong>Embeddings（词向量/嵌入）</strong> 的魔法，就是把人类的语言、句子、甚至图片，变成一串高维的数字（向量）。</p><p>你可以把 Embeddings 想象成<strong>概念的 GPS 坐标</strong>。</p><p>假设我们有一个简单的二维坐标系：X轴代表“是不是水果”，Y轴代表“是不是科技产品”。</p><ul><li>🍎 苹果（吃的那种）：(0.9, 0.1)</li><li>💻 苹果（MacBook）：(0.1, 0.9)</li><li>🍊 橘子：(0.85, 0.05)</li><li>📱 华为：(0.05, 0.88)</li></ul><p>发现了吗？在这个空间里，“吃的苹果”和“橘子”在物理距离上非常近；而“电脑苹果”和“华为”离得非常近。</p><p>在现实的 AI 世界里，这个坐标系不是二维的，而是几百上千维的（比如 OpenAI 的 <code>text-embedding-3-small</code> 是 1536 维）。 <strong>所有的知识，都被打碎、降维，变成了一串串浮点数，悬浮在这个 1536 维的庞大宇宙中。</strong></p><p>不管你用中文说、英文说、换个比喻说，只要你们的**语义（意思）**相近，你们在宇宙中的坐标就会靠得无限近！</p><p>这就是为什么你搜“那家咬了一口的Logo公司”，系统能瞬间给你推算到“Apple”，因为它们在多维空间里的距离最短！</p><hr><h2 id="四、-向量数据库-高维空间的-藏经阁" tabindex="-1">四、 向量数据库：高维空间的“藏经阁” <a class="header-anchor" href="#四、-向量数据库-高维空间的-藏经阁" aria-label="Permalink to &quot;四、 向量数据库：高维空间的“藏经阁”&quot;">​</a></h2>',12)),(t(),o(n,null,{default:A(()=>[s(e,{id:"mermaid-152",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20%E7%9F%A5%E8%AF%86%E5%85%A5%E5%BA%93%0A%20%20%20%20Doc%5B%E4%BC%81%E4%B8%9A%E6%96%87%E6%A1%A3%5D%20--%3E%20Chunk%5B%E5%88%87%E5%88%86%E6%AE%B5%E8%90%BD%5D%20--%3E%20Embed%5B%E5%90%91%E9%87%8F%E5%8C%96%5D%20--%3E%20DB%5B(%E5%90%91%E9%87%8F%E6%95%B0%E6%8D%AE%E5%BA%93)%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20%E5%AE%9E%E6%97%B6%E9%97%AE%E7%AD%94%0A%20%20%20%20Q%5B%E7%94%A8%E6%88%B7%E9%97%AE%E9%A2%98%5D%20--%3E%20QEmbed%5B%E9%97%AE%E9%A2%98%E5%90%91%E9%87%8F%E5%8C%96%5D%20--%3E%20KNN%7BKNN%E6%9C%80%E8%BF%91%E9%82%BB%E6%A3%80%E7%B4%A2%7D%0A%20%20%20%20DB%20--%3E%20KNN%0A%20%20%20%20KNN%20--%3E%20TopK%5BTop%205%20%E7%9B%B8%E5%85%B3%E6%AE%B5%E8%90%BD%5D%0A%20%20%20%20TopK%20--%3E%20LLM%5B%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%BB%84%E8%A3%85%E7%AD%94%E6%A1%88%5D%0A%20%20%20%20end%0A%20%20%20%20style%20DB%20fill%3A%23f9f%2Cstroke%3A%23333%0A"})]),fallback:A(()=>[...E[2]||(E[2]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p>既然所有的文档都被切成了小块，变成了高维坐标（向量），我们就需要一个特殊的地方来存放和查询它们——这就是<strong>向量数据库（Vector Database）</strong>。</p><p>像 Milvus、Pinecone、Qdrant，或者哪怕是加了 pgvector 插件的 PostgreSQL，都在干这件伟大的事情。</p><p>当你向 RAG 系统提出一个问题时，向量数据库是怎么工作的？</p><ol><li><strong>算坐标</strong>：系统先把你的问题也变成一个 1536 维的向量（给你发个GPS定位）。</li><li><strong>找邻居（KNN/ANN 算法）</strong>：系统在宇宙中扫一圈，计算谁离你的坐标最近（通常用“余弦相似度”来计算夹角大小）。</li><li><strong>拿秘籍</strong>：把离你最近的 Top 5 坐标对应的文本片段提取出来，交给大模型去生成答案。</li></ol><blockquote><p><strong>💡 敲黑板总结一下 RAG 的完整修仙流：</strong></p><p>【日常修炼】把公司所有文档切成小块 ➡️ 算成向量（Embeddings） ➡️ 存进向量数据库。 【实战对敌】用户提问 ➡️ 问题算成向量 ➡️ 向量数据库找最相似的文档块 ➡️ 把文档块连同问题一起扔给大模型 ➡️ 大模型总结出完美答案！</p></blockquote><hr><h2 id="五、-结语-rag-才是现阶段的最佳解药" tabindex="-1">五、 结语：RAG 才是现阶段的最佳解药 <a class="header-anchor" href="#五、-结语-rag-才是现阶段的最佳解药" aria-label="Permalink to &quot;五、 结语：RAG 才是现阶段的最佳解药&quot;">​</a></h2><p>在这个大模型一天更新三个版本的疯狂时代，很多人总想着“我要不要自己从头训练一个模型”，或者“我要不要花大价钱去微调（Fine-tuning）”。</p><p>但事实证明，对于99%的企业和开发者来说： <strong>RAG 才是真正的“性价比之王”。</strong></p><ul><li>它<strong>成本极低</strong>（不需要重新训练大模型）。</li><li>它<strong>数据安全</strong>（你的私有数据只存在本地的向量数据库里）。</li><li>它<strong>实时更新</strong>（改个文件，重新向量化一下，AI立刻就知道新规矩了）。</li><li>最重要的是，它真的<strong>治好了 AI 的“胡说八道”</strong>。</li></ul><p>有了 RAG 和向量数据库，AI 终于从一个“爱吹牛的懂王”，变成了一个“带着满箱子绝密文件、随时查阅、严谨输出的顶级秘书”。</p><p>好了，今天的《AI修仙传》就聊到这里。你的公司开始用 RAG 给 AI 装“外脑”了吗？遇到过什么坑？欢迎在评论区留言交流！</p><p>觉得有意思的话，别忘了<strong>点赞、在看、转发</strong>素质三连，我们下期见！👋</p>',13))])}const I=i(g,[["render",B]]);export{h as __pageData,I as default};
